  `WORKSPACE_ID` varchar(20) DEFAULT NULL COMMENT '工作空间ID',
  `CREATE_AT` bigint(20) unsigned DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` bigint(20) unsigned DEFAULT NULL COMMENT '修改时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`),
  KEY `INDEX_TASK_NAME` (`NAME`),
  KEY `INDEX_TASK_LX` (`LX`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='拨测任务表';
/*!40101 SET character_set_client = @saved_cs_client */;

